{
  "scenarios": [
    {
      "id": "M02-01",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "我上周开始膝盖疼痛，医生建议我暂时避免跑步和跳跃，但可以进行游泳或骑自行车。我现在每天只能散步半小时。",
          "assistant": "好的，已记录您的运动限制情况。"
        },
        {
          "user": "补充一下，医生还提到如果疼痛加剧，需要完全停止所有下肢运动，直到复查。目前我还在坚持散步。",
          "assistant": "明白，已更新您的运动限制信息。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者最近被建议避免哪些具体运动？",
          "expected_facts": ["患者被建议暂时避免跑步和跳跃。"],
          "required_groups": [["跑步", "跳跃"]]
        },
        {
          "id": "Q2",
          "query": "在什么情况下患者需要完全停止下肢运动？",
          "expected_facts": ["如果膝盖疼痛加剧，患者需要完全停止所有下肢运动。"],
          "required_groups": [["疼痛加剧", "完全停止", "下肢运动"]]
        }
      ]
    },
    {
      "id": "M02-02",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "我的肩膀受伤后，医生告诉我不能举重物超过两公斤，也不能做扩胸运动。目前我只能进行轻柔的拉伸。",
          "assistant": "收到，已记录您的肩部活动限制。"
        },
        {
          "user": "另外，医生强调如果感到刺痛，应立即停止任何手臂动作并休息。我现在每天只做轻微拉伸。",
          "assistant": "了解，已补充您的注意事项。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者目前被禁止进行哪些手臂相关活动？",
          "expected_facts": ["患者被禁止举重物超过两公斤和做扩胸运动。"],
          "required_groups": [["举重物", "扩胸运动"]]
        },
        {
          "id": "Q2",
          "query": "当出现什么症状时患者必须立即停止手臂动作？",
          "expected_facts": ["如果感到刺痛，患者必须立即停止任何手臂动作。"],
          "required_groups": [["刺痛", "立即停止", "手臂动作"]]
        }
      ]
    },
    {
      "id": "M02-03",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "由于腰部问题，我被要求避免弯腰提东西和长时间坐着。现在我只能短时间站立或缓慢行走。",
          "assistant": "好的，已记录您的腰部活动限制。"
        },
        {
          "user": "医生还说，如果出现麻木感，需要立刻躺下休息。目前我尽量控制活动时间。",
          "assistant": "明白，已更新您的注意事项。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者因腰部问题被禁止哪些动作？",
          "expected_facts": ["患者被禁止弯腰提东西和长时间坐着。"],
          "required_groups": [["弯腰提东西", "长时间坐着"]]
        },
        {
          "id": "Q2",
          "query": "当出现什么感觉时患者需要立即躺下休息？",
          "expected_facts": ["如果出现麻木感，患者需要立刻躺下休息。"],
          "required_groups": [["麻木感", "立刻躺下", "休息"]]
        }
      ]
    },
    {
      "id": "M02-04",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "我的脚踝扭伤后，医生建议不要穿高跟鞋或进行剧烈跑跳。目前我只能穿平底鞋慢慢走。",
          "assistant": "好的，已记录您的脚踝活动限制。"
        },
        {
          "user": "补充一点，如果肿胀加重，需要抬高脚部并减少走动。我现在尽量保持脚部抬高。",
          "assistant": "了解，已补充您的护理建议。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者被建议避免哪些 footwear 和活动？",
          "expected_facts": ["患者被建议避免穿高跟鞋和进行剧烈跑跳。"],
          "required_groups": [["穿高跟鞋", "剧烈跑跳"]]
        },
        {
          "id": "Q2",
          "query": "当脚踝肿胀加重时，患者应采取什么措施？",
          "expected_facts": ["如果肿胀加重，患者需要抬高脚部并减少走动。"],
          "required_groups": [["肿胀加重", "抬高脚部", "减少走动"]]
        }
      ]
    },
    {
      "id": "M02-05",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "因为颈椎不适，我不能低头太久或快速转头。目前我只能缓慢转动头部并保持直立姿势。",
          "assistant": "好的，已记录您的颈部活动限制。"
        },
        {
          "user": "医生提醒，如果出现头晕，需立即停止活动并坐下休息。我现在非常注意头部动作。",
          "assistant": "明白，已更新您的注意事项。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者因颈椎问题被禁止哪些头部动作？",
          "expected_facts": ["患者被禁止低头太久和快速转头。"],
          "required_groups": [["低头太久", "快速转头"]]
        },
        {
          "id": "Q2",
          "query": "当出现头晕时，患者应该怎么做？",
          "expected_facts": ["如果出现头晕，患者需立即停止活动并坐下休息。"],
          "required_groups": [["头晕", "立即停止", "坐下休息"]]
        }
      ]
    },
    {
      "id": "M02-06",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "我的手腕受伤后，医生建议不要用力握拳或提重物。目前我只能轻轻抓握轻物。",
          "assistant": "好的，已记录您的手腕活动限制。"
        },
        {
          "user": "另外，如果感到刺痛，需要停止使用手部并冰敷。我现在尽量避免用力。",
          "assistant": "了解，已补充您的护理建议。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者被建议避免哪些手部动作？",
          "expected_facts": ["患者被建议避免用力握拳和提重物。"],
          "required_groups": [["用力握拳", "提重物"]]
        },
        {
          "id": "Q2",
          "query": "当手腕感到刺痛时，患者应采取什么措施？",
          "expected_facts": ["如果感到刺痛，患者需要停止使用手部并冰敷。"],
          "required_groups": [["刺痛", "停止使用手部", "冰敷"]]
        }
      ]
    },
    {
      "id": "M02-07",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "由于背部拉伤，我不能做仰卧起坐或搬重物。目前我只能平躺休息或缓慢翻身。",
          "assistant": "好的，已记录您的背部活动限制。"
        },
        {
          "user": "医生还说，如果疼痛扩散到腿部，需要立即就医。我现在尽量保持静止。",
          "assistant": "明白，已更新您的注意事项。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者因背部拉伤被禁止哪些动作？",
          "expected_facts": ["患者被禁止做仰卧起坐和搬重物。"],
          "required_groups": [["仰卧起坐", "搬重物"]]
        },
        {
          "id": "Q2",
          "query": "当疼痛扩散到腿部时，患者应如何处理？",
          "expected_facts": ["如果疼痛扩散到腿部，患者需要立即就医。"],
          "required_groups": [["疼痛扩散", "腿部", "立即就医"]]
        }
      ]
    },
    {
      "id": "M02-08",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "我的肘关节发炎后，医生建议不要弯曲超过90度或重复同一动作。目前我只能保持手臂伸直。",
          "assistant": "好的，已记录您的肘关节活动限制。"
        },
        {
          "user": "补充一下，如果出现红肿，需要冷敷并减少活动。我现在尽量保持手臂不动。",
          "assistant": "了解，已补充您的护理建议。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者被建议避免哪些肘关节动作？",
          "expected_facts": ["患者被建议避免弯曲超过90度和重复同一动作。"],
          "required_groups": [["弯曲超过90度", "重复同一动作"]]
        },
        {
          "id": "Q2",
          "query": "当肘关节出现红肿时，患者应采取什么措施？",
          "expected_facts": ["如果出现红肿，患者需要冷敷并减少活动。"],
          "required_groups": [["红肿", "冷敷", "减少活动"]]
        }
      ]
    },
    {
      "id": "M02-09",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "由于髋关节置换术后，我不能交叉双腿或深蹲。目前我只能坐在高椅子上。",
          "assistant": "好的，已记录您的髋关节活动限制。"
        },
        {
          "user": "医生提醒，如果感到异常疼痛，需立即联系医院。我现在非常小心坐姿。",
          "assistant": "明白，已更新您的注意事项。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者术后被禁止哪些髋关节动作？",
          "expected_facts": ["患者被禁止交叉双腿和深蹲。"],
          "required_groups": [["交叉双腿", "深蹲"]]
        },
        {
          "id": "Q2",
          "query": "当感到异常疼痛时，患者应如何处理？",
          "expected_facts": ["如果感到异常疼痛，患者需立即联系医院。"],
          "required_groups": [["异常疼痛", "立即联系", "医院"]]
        }
      ]
    },
    {
      "id": "M02-10",
      "category": "运动限制与日常活动",
      "turns": [
        {
          "user": "我的手指关节炎导致不能紧握物体或长时间打字。目前我只能用单手操作轻物。",
          "assistant": "好的，已记录您的手指活动限制。"
        },
        {
          "user": "另外，如果关节僵硬，需要热敷并做轻柔伸展。我现在尽量控制使用时间。",
          "assistant": "了解，已补充您的护理建议。"
        }
      ],
      "queries": [
        {
          "id": "Q1",
          "query": "患者因关节炎被禁止哪些手指动作？",
          "expected_facts": ["患者被禁止紧握物体和长时间打字。"],
          "required_groups": [["紧握物体", "长时间打字"]]
        },
        {
          "id": "Q2",
          "query": "当关节僵硬时，患者应采取什么措施？",
          "expected_facts": ["如果关节僵硬，患者需要热敷并做轻柔伸展。"],
          "required_groups": [["关节僵硬", "热敷", "轻柔伸展"]]
        }
      ]
    }
  ]
}
